{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Vol Desk Data",
    "url": "http://localhost:7801",
    "operation": "add",
    "widgets_json": {
      "vol_cockpit_table": {
        "name": "Vol Cockpit Table",
        "description": "Implied and realized volatility by tenor.",
        "endpoint": "/vol-cockpit-table",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "form": [
          {
            "paramName": "tenor",
            "type": "text",
            "label": "Tenor",
            "value": "1M",
            "description": "Vol Cockpit Table focus field."
          }
        ]
      },
      "vix_advanced": {
        "name": "VIX Advanced Chart",
        "description": "TradingView advanced charting for VIX futures.",
        "endpoint": "/udf",
        "type": "advanced_charting",
        "gridData": {
          "w": 20,
          "h": 20
        },
        "data": {
          "defaultSymbol": "VIX",
          "updateFrequency": 60000
        }
      }
    }
  }
}

{
  "done": false,
  "tool": "add_generative_widget",
  "args": {
    "dashboard_id": "dash_002",
    "name": "Vol Cockpit",
    "widget_type": "note",
    "data": "Vol Cockpit is live from Vol Desk Data: vol cockpit ready."
  }
}
